package com.flashlearn.data.repository

import com.flashlearn.database.*
import com.flashlearn.domain.model.*
import com.flashlearn.domain.repository.*
import java.util.UUID
import org.json.JSONArray
import javax.inject.Inject

object Mappers {
    fun concept(e: ConceptEntity)=Concept(e.id,EntryType.valueOf(e.entryType),e.categoryId,e.favorite,e.active,e.createdAt,e.updatedAt)
    fun concept(e: Concept)=ConceptEntity(e.id,e.entryType.name,e.categoryId,e.favorite,e.active,e.createdAt,e.updatedAt)
    fun content(e: ContentEntity)=Content(e.id,e.conceptId,e.languageCode,e.text,e.canonicalKey,e.notes,e.pronunciation,e.example,e.translationIndex,e.grammarNote,e.possibleCorrection)
    fun content(e: Content)=ContentEntity(e.id,e.conceptId,e.languageCode,e.text,e.canonicalKey,e.notes,e.pronunciation,e.example,e.translationIndex,e.grammarNote,e.possibleCorrection)
    fun learning(e: LearningStateEntity)=LearningState(e.id,e.conceptId,Stage.valueOf(e.stage),e.nextReviewAt,e.monthlyWrongCount,e.hasPathFailure,e.totalCorrect,e.totalWrong,e.lastReviewedAt)
    fun learning(e: LearningState)=LearningStateEntity(e.id,e.conceptId,e.stage.name,e.nextReviewAt,e.monthlyWrongCount,e.hasPathFailure,e.totalCorrect,e.totalWrong,e.lastReviewedAt)
    fun difficulty(e: DifficultyStateEntity)=DifficultyState(e.id,e.conceptId,VocabularyDifficulty.valueOf(e.current),e.consecutiveCorrect,e.consecutiveWrong,e.hasReachedVeryHard)
    fun difficulty(e: DifficultyState)=DifficultyStateEntity(e.id,e.conceptId,e.current.name,e.consecutiveCorrect,e.consecutiveWrong,e.hasReachedVeryHard)
    fun tag(e: TagEntity)=Tag(e.id,e.name)
    fun tag(e: Tag)=TagEntity(e.id,e.name)
    fun conceptTag(e: ConceptTag)=ConceptTagEntity(e.conceptId,e.tagId)
    fun conceptTag(e: ConceptTagEntity)=ConceptTag(e.conceptId,e.tagId)
    fun history(e: ReviewHistory)=ReviewHistoryEntity(e.id,e.sessionId,e.reviewAttemptId,e.conceptId,e.reviewedAt,e.isCorrect,e.reviewType.name)
    fun history(e: ReviewHistoryEntity)=ReviewHistory(e.id,e.sessionId,e.reviewAttemptId,e.conceptId,e.reviewedAt,e.isCorrect,ReviewType.valueOf(e.reviewType))
    fun session(e: ReviewSession)=ReviewSessionEntity(e.id,e.startedAt,e.endedAt,e.reviewType.name)
    fun session(e: ReviewSessionEntity)=ReviewSession(e.id,e.startedAt,e.endedAt,ReviewType.valueOf(e.reviewType))
    fun category(e: CategoryEntity)=Category(e.id,e.name); fun category(e: Category)=CategoryEntity(e.id,e.name)
    fun parserMetadata(e: ParserMetadataEntity): ParserMetadata = ParserMetadata(JSONArray(e.breakdownJson).let { a->(0 until a.length()).map{a.getString(it)} },JSONArray(e.relationshipsJson).let{a->(0 until a.length()).map{a.getString(it)}},JSONArray(e.variantsJson).let{a->(0 until a.length()).map{a.getString(it)}},e.confidence)
    fun parserMetadata(id: UUID,v: ParserMetadata)=ParserMetadataEntity(id,JSONArray().apply{v.breakdown.forEach(::put)}.toString(),JSONArray().apply{v.relationships.forEach(::put)}.toString(),JSONArray().apply{v.variants.forEach(::put)}.toString(),v.confidence.coerceIn(0.0,1.0))
    fun relation(e: VocabularyRelationEntity)=VocabularyRelation(e.id,e.sourceConceptId,e.targetConceptId,VocabularyRelationType.valueOf(e.relationType),e.unresolvedText); fun relation(e: VocabularyRelation)=VocabularyRelationEntity(e.id,e.sourceConceptId,e.targetConceptId,e.relationType.name,e.unresolvedText)
    fun variant(e: VocabularyVariantEntity)=VocabularyVariant(e.id,e.conceptId,e.text,VocabularyVariantType.valueOf(e.variantType)); fun variant(e: VocabularyVariant)=VocabularyVariantEntity(e.id,e.conceptId,e.text,e.variantType.name)
    fun reviewQueue(e: ReviewQueueEntity)=ReviewQueueItem(e.id,e.conceptId,e.sourceText,e.targetText,e.confidence,e.possibleCorrection,ReviewQueueStatus.valueOf(e.status),e.lineNumber,e.warning); fun reviewQueue(e: ReviewQueueItem)=ReviewQueueEntity(e.id,e.conceptId,e.sourceText,e.targetText,e.confidence.coerceIn(0.0,1.0),e.possibleCorrection,e.status.name,e.lineNumber,e.warning)
    fun language(e: LanguageEntity)=Language(e.code,e.name,e.active); fun language(e: Language)=LanguageEntity(e.code,e.name,e.active)
    fun languagePair(e: LanguagePairEntity)=LanguagePair(e.sourceLanguageCode,e.targetLanguageCode,e.active); fun languagePair(e: LanguagePair)=LanguagePairEntity(e.sourceLanguageCode,e.targetLanguageCode,e.active)
}
class RoomConceptRepository @Inject constructor(private val dao: ConceptDao): ConceptRepository { override suspend fun insert(c:Concept)=dao.insert(Mappers.concept(c)).let{c.id}; override suspend fun get(id:UUID)=dao.getById(id)?.let(Mappers::concept); override suspend fun getAllActive()=dao.getAllActive().map(Mappers::concept); override suspend fun searchActive(q:String)=dao.searchActive(q).map(Mappers::concept); override suspend fun update(c:Concept)=dao.update(Mappers.concept(c)); override suspend fun softDelete(id:UUID,now:java.time.Instant)=dao.softDelete(id,now) }
class RoomContentRepository @Inject constructor(private val dao:ContentDao): ContentRepository { override suspend fun findByUuid(id:UUID)=dao.getById(id)?.let(Mappers::content); override suspend fun find(id:UUID,lang:String)=dao.getByConceptIdAndLanguage(id,lang)?.let(Mappers::content); override suspend fun findAll(id:UUID,lang:String)=dao.getAllByConceptIdAndLanguage(id,lang).map(Mappers::content); override suspend fun findForConcepts(ids:List<UUID>)=if(ids.isEmpty())emptyList() else ids.distinct().chunked(500).flatMap{dao.getForConcepts(it).map(Mappers::content)}; override suspend fun getAll()=dao.getAll().map(Mappers::content); override suspend fun upsert(c:Content){if(dao.getById(c.id)==null)dao.insert(Mappers.content(c))else dao.update(Mappers.content(c))}; override suspend fun insertTranslation(c:Content)=dao.insert(Mappers.content(c)) }
class RoomLearningStateRepository @Inject constructor(private val dao:LearningStateDao): LearningStateRepository { override suspend fun get(id:UUID)=dao.getByConceptId(id)?.let(Mappers::learning); override suspend fun upsert(s:LearningState)=dao.upsert(Mappers.learning(s)); override suspend fun getAllByStage(s:Stage)=dao.getAllByStage(s.name).map(Mappers::learning); override suspend fun getDueNonLearned(n:java.time.Instant)=dao.getAllDueNonLearned(n).map(Mappers::learning); override suspend fun getAll()=dao.getAll().map(Mappers::learning) }
class RoomDifficultyStateRepository @Inject constructor(private val dao:DifficultyStateDao): DifficultyStateRepository { override suspend fun get(id:UUID)=dao.getByConceptId(id)?.let(Mappers::difficulty); override suspend fun upsert(s:DifficultyState)=dao.upsert(Mappers.difficulty(s)); override suspend fun delete(id:UUID)=dao.deleteByConceptId(id); override suspend fun getAll()=dao.getAll().map(Mappers::difficulty) }
class RoomParserMetadataRepository @Inject constructor(private val dao:ParserMetadataDao): ParserMetadataRepository { override suspend fun get(id:UUID)=dao.getByConceptId(id)?.let(Mappers::parserMetadata); override suspend fun upsert(id:UUID,v:ParserMetadata)=dao.upsert(Mappers.parserMetadata(id,v)); override suspend fun getAll()=dao.getAll().map{it.conceptId to Mappers.parserMetadata(it)} }
class RoomConceptTagRepository @Inject constructor(private val dao:ConceptTagDao): ConceptTagRepository { override suspend fun insert(v:ConceptTag)=dao.insert(Mappers.conceptTag(v)); override suspend fun getTagsForConcept(id:UUID)=dao.getTagIdsForConcept(id); override suspend fun getConceptsForTag(id:UUID)=dao.getConceptIdsForTag(id); override suspend fun getAll()=dao.getAll().map(Mappers::conceptTag) }
class RoomTagRepository @Inject constructor(private val dao:TagDao): TagRepository { override suspend fun getAll()=dao.getAll().map(Mappers::tag); override suspend fun insert(t:Tag)=dao.insert(Mappers.tag(t)).let{t.id}; override suspend fun update(t:Tag)=dao.update(Mappers.tag(t)); override suspend fun delete(id:UUID)=dao.deleteById(id) }
class RoomReviewHistoryRepository @Inject constructor(private val dao:ReviewHistoryDao): ReviewHistoryRepository { override suspend fun insert(e:ReviewHistory)=dao.insert(Mappers.history(e)); override suspend fun existsByAttemptId(s:UUID,a:UUID)=dao.existsByAttemptId(s,a); override suspend fun getAll()=dao.getAll().map(Mappers::history) }
class RoomSettingsRepository @Inject constructor(private val dao:SettingsDao): SettingsRepository { override suspend fun getInt(k:String,d:Int)=dao.getByKey(k)?.value?.toIntOrNull()?:d; suspend fun setInt(k:String,v:Int)=dao.put(SettingsEntity(k,v.toString(),java.time.Instant.now())) }
class RoomDataVersionRepository @Inject constructor(private val dao:SettingsDao): DataVersionRepository { override suspend fun getConceptDataVersion()=dao.getByKey(KEY_C)?.value?.toIntOrNull()?:0; override suspend fun getContentDataVersion()=dao.getByKey(KEY_T)?.value?.toIntOrNull()?:0; override suspend fun setConceptDataVersion(v:Int)=dao.put(SettingsEntity(KEY_C,v.toString(),java.time.Instant.now())); override suspend fun setContentDataVersion(v:Int)=dao.put(SettingsEntity(KEY_T,v.toString(),java.time.Instant.now())); companion object{const val KEY_C="data_version.concept";const val KEY_T="data_version.content"} }
class RoomReviewSessionRepository @Inject constructor(private val dao:ReviewSessionDao):ReviewSessionRepository{override suspend fun insert(s:ReviewSession)=dao.insert(Mappers.session(s));override suspend fun get(id:UUID)=dao.getById(id)?.let(Mappers::session);override suspend fun update(s:ReviewSession)=dao.update(Mappers.session(s))}
class RoomCategoryRepository @Inject constructor(private val dao:CategoryDao):CategoryRepository{override suspend fun getAll()=dao.getAll().map(Mappers::category);override suspend fun findByName(n:String)=dao.findByName(n)?.let(Mappers::category);override suspend fun insert(c:Category)=dao.insert(Mappers.category(c)).let{c.id}}
class RoomVocabularyRelationRepository @Inject constructor(private val dao:VocabularyRelationDao):VocabularyRelationRepository{override suspend fun insert(v:VocabularyRelation)=dao.insert(Mappers.relation(v));override suspend fun getForConcept(id:UUID)=dao.getForConcept(id).map(Mappers::relation);override suspend fun getAll()=dao.getAll().map(Mappers::relation)}
class RoomVocabularyVariantRepository @Inject constructor(private val dao:VocabularyVariantDao):VocabularyVariantRepository{override suspend fun insert(v:VocabularyVariant)=dao.insert(Mappers.variant(v));override suspend fun getForConcept(id:UUID)=dao.getForConcept(id).map(Mappers::variant);override suspend fun getAll()=dao.getAll().map(Mappers::variant)}
class RoomReviewQueueRepository @Inject constructor(private val dao:ReviewQueueDao):ReviewQueueRepository{override suspend fun upsert(v:ReviewQueueItem)=dao.upsert(Mappers.reviewQueue(v));override suspend fun getPending()=dao.getPending().map(Mappers::reviewQueue);override suspend fun getAll()=dao.getAll().map(Mappers::reviewQueue);override suspend fun update(v:ReviewQueueItem)=dao.update(Mappers.reviewQueue(v))}
class RoomLanguageRepository @Inject constructor(private val dao:LanguageDao,private val pairDao:LanguagePairDao):LanguageRepository{override suspend fun getAll()=dao.getAll().map(Mappers::language);override suspend fun getActive()=dao.getActive().map(Mappers::language);override suspend fun getPairs()=pairDao.getAll().map(Mappers::languagePair);override suspend fun getActivePairs()=pairDao.getActive().map(Mappers::languagePair);override suspend fun upsert(v:Language)=dao.upsert(Mappers.language(v));override suspend fun upsertPair(v:LanguagePair)=pairDao.upsert(Mappers.languagePair(v))}
